// No transpilation: copy the readable source into an inspectable source manifest.
// Build a standard ZIP using Node's built-in APIs, with no npm dependencies.
import { readFile, writeFile, mkdir, copyFile } from 'node:fs/promises';
import { deflateRawSync } from 'node:zlib';
const paths=['README.md','package.json','.gitignore','.devcontainer/devcontainer.json',
  'dist/index.html','dist/app.js','dist/data.js','dist/compose.js','dist/styles.css','dist/layout.css','dist/favicon.svg',
  'dist/source.html','dist/source.js','dist/source.css','scripts/server.mjs','scripts/build.mjs','scripts/start-codespace.sh','tests/compose.test.mjs'];
const files={};
for(const path of paths) files[path]=await readFile(new URL('../'+path,import.meta.url),'utf8');
await writeFile(new URL('../dist/source-code.json',import.meta.url),JSON.stringify(files,null,2));

function crc32(buffer){
  let crc=0xffffffff;
  for(const byte of buffer){crc^=byte;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}
  return (crc^0xffffffff)>>>0;
}
const local=[],central=[];
let offset=0;
for(const [path,contents] of Object.entries(files)){
  const name=Buffer.from('speakcare/'+path),data=Buffer.from(contents),compressed=deflateRawSync(data),crc=crc32(data);
  const header=Buffer.alloc(30);header.writeUInt32LE(0x04034b50,0);header.writeUInt16LE(20,4);header.writeUInt16LE(0x800,6);header.writeUInt16LE(8,8);header.writeUInt16LE(23585,12);header.writeUInt32LE(crc,14);header.writeUInt32LE(compressed.length,18);header.writeUInt32LE(data.length,22);header.writeUInt16LE(name.length,26);
  local.push(header,name,compressed);
  const entry=Buffer.alloc(46);entry.writeUInt32LE(0x02014b50,0);entry.writeUInt16LE(20,4);entry.writeUInt16LE(20,6);entry.writeUInt16LE(0x800,8);entry.writeUInt16LE(8,10);entry.writeUInt16LE(23585,14);entry.writeUInt32LE(crc,16);entry.writeUInt32LE(compressed.length,20);entry.writeUInt32LE(data.length,24);entry.writeUInt16LE(name.length,28);entry.writeUInt32LE(offset,42);central.push(entry,name);
  offset+=header.length+name.length+compressed.length;
}
const directory=Buffer.concat(central),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50,0);end.writeUInt16LE(paths.length,8);end.writeUInt16LE(paths.length,10);end.writeUInt32LE(directory.length,12);end.writeUInt32LE(offset,16);
await writeFile(new URL('../dist/SpeakCare-source.zip',import.meta.url),Buffer.concat([...local,directory,end]));
// GitHub Pages can publish /docs directly from main without an Actions workflow.
await mkdir(new URL('../docs/', import.meta.url), {recursive:true});
const publicFiles=[...paths.filter(path=>path.startsWith('dist/')).map(path=>path.slice(5)), 'source-code.json','SpeakCare-source.zip'];
for(const name of publicFiles) await copyFile(new URL('../dist/'+name,import.meta.url),new URL('../docs/'+name,import.meta.url));
await writeFile(new URL('../docs/.nojekyll',import.meta.url),'');
console.log(`SpeakCare is ready: ${paths.length} source files, source viewer and ZIP. GitHub Pages output: docs/.`);

tests/compose.test.mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { composeMessage, discomfortMessage, filterPhrases } from '../dist/compose.js';
import { phrases, parts, feelings, times } from '../dist/data.js';

test('selected phrases keep the patient’s selection order', () => {
  assert.equal(composeMessage(['pain','water'],phrases,'en',null), 'I am in pain. I would like some water, please.');
});
test('custom text is preserved verbatim, including medical terms and negation', () => {
  const text='I am NOT allergic to penicillin. I do not want an injection.';
  assert.equal(composeMessage([],phrases,'en',null,text),text);
});
test('changing the board language translates only the catalog, never custom text', () => {
  assert.equal(composeMessage(['pain'],phrases,'es',null,'Keep my words.'),'Tengo dolor. Keep my words.');
});
test('no description is inferred when the user has not selected an area', () => {
  assert.equal(discomfortMessage({location:'',feeling:'sharp',intensity:7},'en',parts,feelings,times),'');
});
test('intensity zero is preserved rather than dropped as a falsy value', () => {
  assert.equal(discomfortMessage({location:'leftArm',feeling:'tingling',intensity:0,timing:'now'},'en',parts,feelings,times),'I feel tingling in my left arm. The intensity is 0 out of 10. It is happening now.');
});
test('unknown intensity and timing are never invented', () => {
  assert.equal(discomfortMessage({location:'head',feeling:'other',intensity:null,timing:''},'en',parts,feelings,times),'I feel discomfort in my head.');
});
test('left and right are distinct in both language catalogs', () => {
  assert.match(discomfortMessage({location:'rightArm',feeling:'aching'},'es',parts,feelings,times),/brazo derecho/);
  assert.match(discomfortMessage({location:'leftArm',feeling:'aching'},'es',parts,feelings,times),/brazo izquierdo/);
});
test('search respects category and selected language; keyword search finds synonyms', () => {
  assert.equal(filterPhrases(phrases,'all','bathroom','en')[0].id,'restroom');
  assert.equal(filterPhrases(phrases,'all','agua','es')[0].id,'water');
  assert.equal(filterPhrases(phrases,'questions','water','en').length,0);
});
test('every catalog entry has a unique ID, icon, category, and both translations', () => {
  assert.equal(new Set(phrases.map(p=>p.id)).size,phrases.length);
  for(const p of phrases) for(const language of ['en','es']) {
    assert.ok(p[language].label);assert.ok(p[language].text);assert.ok(p.icon);assert.ok(p.category);
  }
});
test('favorites only returns known selected catalog IDs', () => {
  assert.deepEqual(filterPhrases(phrases,'all','','en',true,['water','invalid']).map(p=>p.id),['water']);
});
